package vn.hust.restaurant.service;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.Base64;import javax.net.ssl.SSLSocketFactory;import vn.hust.restaurant.config.AppConfig;
public class SmtpOtpService implements OtpService{
 public void send(String to,String code)throws Exception{String user=AppConfig.app("smtp.username","");String pass=AppConfig.app("smtp.appPassword","");if(user.isBlank()||pass.isBlank())throw new IllegalStateException("Chưa cấu hình Gmail SMTP");String host=AppConfig.app("smtp.host","smtp.gmail.com");int port=AppConfig.appInt("smtp.port",465);try(Socket s=SSLSocketFactory.getDefault().createSocket(host,port);BufferedReader r=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8))){expect(r,220);cmd(w,r,"EHLO localhost",250);cmd(w,r,"AUTH LOGIN",334);cmd(w,r,Base64.getEncoder().encodeToString(user.getBytes(StandardCharsets.UTF_8)),334);cmd(w,r,Base64.getEncoder().encodeToString(pass.getBytes(StandardCharsets.UTF_8)),235);cmd(w,r,"MAIL FROM:<"+user+">",250);cmd(w,r,"RCPT TO:<"+to+">",250);cmd(w,r,"DATA",354);String msg="From: "+user+"\r\nTo: "+to+"\r\nSubject: Ma OTP HTQL Nha Hang\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\nMa OTP cua ban la: "+code+". Ma co hieu luc 5 phut.\r\n.";cmd(w,r,msg,250);cmd(w,r,"QUIT",221);}}
 public String deliveryDescription(){return "Gửi OTP qua Gmail SMTP";}private static void cmd(BufferedWriter w,BufferedReader r,String c,int code)throws Exception{w.write(c+"\r\n");w.flush();expect(r,code);}private static void expect(BufferedReader r,int code)throws Exception{String line=r.readLine();if(line==null||!line.startsWith(String.valueOf(code)))throw new IOException("SMTP: "+line);while(line.length()>3&&line.charAt(3)=='-')line=r.readLine();}
}
